const defaults={schemaVersion:20,version:22,healthSync:{provider:'apple-health',watch:'Amazfit GTR 4',connected:false,lastSync:null},savedMeals:[],learnedFoods:[],foodHistory:[],favorites:[],profile:{pushGoal:100,kcalGoal:2300,deficitGoal:400,basalKcal:1834,proteinGoal:165,carbGoal:250,fatGoal:70,activityAdjust:true,activityFactor:.7,dayCutoffHour:2,maintenanceLearning:true,geminiEndpoint:'https://susu-food-ai.javiperezespanol.workers.dev'},days:{},checkins:[]};
