const PHOTO_DB='susu-media',PHOTO_STORE='photos';
function photoDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open(PHOTO_DB,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains(PHOTO_STORE))r.result.createObjectStore(PHOTO_STORE)};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function photoPut(data,key=id()){const db=await photoDB();return new Promise((resolve,reject)=>{const tx=db.transaction(PHOTO_STORE,'readwrite');tx.objectStore(PHOTO_STORE).put(data,key);tx.oncomplete=()=>{db.close();resolve('idb:'+key)};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function photoGet(ref){if(!ref)return'';if(!String(ref).startsWith('idb:'))return ref;const db=await photoDB(),key=String(ref).slice(4);return new Promise((resolve,reject)=>{const tx=db.transaction(PHOTO_STORE,'readonly'),r=tx.objectStore(PHOTO_STORE).get(key);r.onsuccess=()=>{db.close();resolve(r.result||'')};r.onerror=()=>{db.close();reject(r.error)}})}
async function photoDelete(ref){if(!String(ref||'').startsWith('idb:'))return;const db=await photoDB(),key=String(ref).slice(4);return new Promise((resolve,reject)=>{const tx=db.transaction(PHOTO_STORE,'readwrite');tx.objectStore(PHOTO_STORE).delete(key);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function migratePhotosToIDB(){let changed=false;for(const c of s.checkins){if(!Array.isArray(c.photos))continue;for(let i=0;i<c.photos.length;i++){if(typeof c.photos[i]==='string'&&c.photos[i].startsWith('data:image/')){try{c.photos[i]=await photoPut(c.photos[i]);changed=true}catch{}}}}for(const d of Object.values(s.days||{})){for(const m of d.meals||[]){if(typeof m.photoRef==='string'&&m.photoRef.startsWith('data:image/')){try{m.photoRef=await photoPut(m.photoRef);changed=true}catch{}}}}if(changed)save()}
async function hydratePhotoImages(root=document){for(const el of root.querySelectorAll('[data-photo-ref]')){try{el.src=await photoGet(el.dataset.photoRef)}catch{}}}

function susuDayKey(date=new Date()){const d=new Date(date);const cutoff=Math.max(0,Math.min(23,Number(s?.profile?.dayCutoffHour??2)));if(d.getHours()<cutoff)d.setDate(d.getDate()-1);return d.toLocaleDateString('en-CA')}
const today=()=>susuDayKey();
// Apple Salud registra días naturales (00:00–23:59). Comidas y flexiones
// conservan el corte configurable de SU SU (02:00 por defecto).
function calendarDayKey(date=new Date()){const d=new Date(date);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function healthKeyFor(k=today()){return k===today()?calendarDayKey():k}

const n=v=>Number(v)||0;
const id=()=>crypto.randomUUID?.()||`${Date.now()}-${Math.random()}`;
const esc=(x='')=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function fresh(){return JSON.parse(JSON.stringify(defaults))}
function migrate(old){const out=fresh();out.profile={...out.profile,...(old.profile||{})};out.checkins=(old.measurements||[]).map((m,i)=>({...m,id:`old-${i}`,photos:[]}));for(const [k,d] of Object.entries(old.days||{})){out.days[k]={pushEvents:n(d.pushups)?[{id:id(),amount:n(d.pushups),at:`${k}T12:00:00`}]:[],pullEvents:n(d.pullups)?[{id:id(),amount:n(d.pullups),at:`${k}T12:00:00`}]:[],meals:d.meals||[]};}return out}
function normalize(v){const out={...fresh(),...v,profile:{...fresh().profile,...v?.profile},days:v?.days||{},checkins:Array.isArray(v?.checkins)?v.checkins:[],savedMeals:Array.isArray(v?.savedMeals)?v.savedMeals:[],learnedFoods:Array.isArray(v?.learnedFoods)?v.learnedFoods:[],foodHistory:Array.isArray(v?.foodHistory)?v.foodHistory:[],favorites:Array.isArray(v?.favorites)?v.favorites:[],healthSync:{...fresh().healthSync,...(v?.healthSync||{})}};out.schemaVersion=20;out.version=22;for(const d of Object.values(out.days)){d.pushEvents=Array.isArray(d.pushEvents)?d.pushEvents:[];d.pullEvents=Array.isArray(d.pullEvents)?d.pullEvents:[];d.meals=Array.isArray(d.meals)?d.meals:[];d.activityEvents=Array.isArray(d.activityEvents)?d.activityEvents:[];d.health=d.health&&typeof d.health==='object'?d.health:{steps:0,activeKcal:0,distanceKm:0,exerciseMin:0,sleepMin:0,restingHr:0,heartRate:0,weight:0,bodyFat:0,bmi:0,workouts:[],source:null,updatedAt:null}}return out}
function load(){try{const current=JSON.parse(localStorage.getItem(KEY));if(current){if(Number(current.version||current.schemaVersion||0)<22){try{localStorage.setItem('susu-auto-backup',JSON.stringify({createdAt:new Date().toISOString(),fromVersion:current.version||current.schemaVersion||0,data:current}))}catch{}}return normalize(current);}for(const legacyKey of [V6_KEY,V5_KEY]){const legacy=JSON.parse(localStorage.getItem(legacyKey));if(legacy){const m=normalize(legacy);localStorage.setItem('susu-prev',JSON.stringify(legacy));localStorage.setItem(KEY,JSON.stringify(m));return m}}const old=JSON.parse(localStorage.getItem(OLD_KEY));if(old){const m=normalize(migrate(old));localStorage.setItem('susu-prev',JSON.stringify(old));localStorage.setItem(KEY,JSON.stringify(m));return m}}catch{}return fresh()}
function save(){try{localStorage.setItem(KEY,JSON.stringify(s));return true}catch(err){console.error('SU SU save failed',err);toast('No se pudo guardar · libera espacio');return false}}
function day(k=today()){return s.days[k]||(s.days[k]={pushEvents:[],pullEvents:[],meals:[],activityEvents:[],health:{steps:0,activeKcal:0,distanceKm:0,exerciseMin:0,sleepMin:0,restingHr:0,heartRate:0,weight:0,bodyFat:0,bmi:0,workouts:[],source:null,updatedAt:null}})}
function exerciseTotal(type,k=today()){const d=s.days[k];return (d?.[type+'Events']||[]).reduce((a,e)=>a+Math.max(0,Math.round(Number(e.amount)||0)),0)}
function dayTotals(d=day()){return (d.meals||[]).reduce((a,m)=>({kcal:a.kcal+n(m.kcal),p:a.p+n(m.p),c:a.c+n(m.c),f:a.f+n(m.f)}),{kcal:0,p:0,c:0,f:0})}
function keyDate(k=today()){return new Date(k+'T12:00:00')}
function shiftKey(k,delta){const d=keyDate(k);d.setDate(d.getDate()+delta);return d.toLocaleDateString('en-CA')}
function monthKeys(){const key=today(),base=keyDate(key),out=[];for(let i=1;i<=base.getDate();i++)out.push(new Date(base.getFullYear(),base.getMonth(),i,12).toLocaleDateString('en-CA'));return out}
function pushAvg(){const ks=monthKeys();return Math.round(ks.reduce((a,k)=>a+(s.days[k]?.pushEvents||[]).reduce((x,e)=>x+n(e.amount),0),0)/Math.max(1,ks.length))}
function last7PushAvg(){let total=0,k=today();for(let i=0;i<7;i++)total+=exerciseTotal('push',shiftKey(k,-i));return Math.round(total/7)}
function healthDay(k=calendarDayKey()){return s.days[k]?.health||{steps:0,activeKcal:0,distanceKm:0,exerciseMin:0,sleepMin:0,restingHr:0,heartRate:0,weight:0,bodyFat:0,bmi:0,workouts:[],source:null,updatedAt:null}}
function manualActivityKcal(k=today()){return (s.days[k]?.activityEvents||[]).reduce((a,e)=>a+Math.max(0,n(e.kcal)),0)}
function activityKcal(k=today()){const h=healthDay(healthKeyFor(k));return n(h.activeKcal)>0?n(h.activeKcal):manualActivityKcal(k)}
function activitySource(k=today()){const h=healthDay(healthKeyFor(k));return n(h.activeKcal)>0?(h.source||'reloj/móvil'):(manualActivityKcal(k)>0?'manual':null)}
function dailyEnergy(k=today()){
 const h=healthDay(healthKeyFor(k)), basal=Math.max(1000,Math.min(3500,n(s.profile.basalKcal)||1834));
 const resting=n(h.restingKcal)>0?n(h.restingKcal):Math.round(basal*1.1);
 const active=activityKcal(k), deficit=Math.max(0,Math.min(1000,n(s.profile.deficitGoal)??400));
 return {resting,active,deficit,maintenance:Math.round(resting+active),target:Math.max(1200,Math.round(resting+active-deficit)),measuredResting:n(h.restingKcal)>0,hasActivity:n(h.activeKcal)>0||manualActivityKcal(k)>0};
}
function adjustedKcalGoal(k=today()){return dailyEnergy(k).target}
function dayStatus(k){const d=s.days[k]||{meals:[]},t=dayTotals(d),push=exerciseTotal('push',k);return {push:push>=s.profile.pushGoal,protein:t.p>=s.profile.proteinGoal,both:push>=s.profile.pushGoal&&t.p>=s.profile.proteinGoal,pushTotal:push,p:t.p,kcal:t.kcal}}
function motivation(push,goal){const r=goal?push/goal:0;const pools=r>=1.5?['PAPÁ SE HA CALENTADO','HOY HAS VENIDO A HACER DAÑO','¿PERO TÚ QUÉ COJONES HACES? 😂']:r>=1?['VAMOOOOOS 🔥','PAPÁ HA CUMPLIDO','OBJETIVO REVENTADO','ASÍ SÍ, CABRÓN']:r>=.75?['YA LO TIENES, CABRÓN','NO ME PARES AHORA','ÚLTIMO EMPUJÓN']:r>=.25?['VAMOS PAPÁÁÁ','DALE LOCOOO','SIGUE DÁNDOLE','NO PARAMOS']:['¿ERES UN LADYBOY?','DALE LOCO, QUE NO SE HACE SOLO','¿PERO VAS A EMPEZAR O QUÉ?'];return pools[Math.abs((push+new Date().getDate()))%pools.length]}
function mondayOfKey(k=today()){const x=keyDate(k),wd=(x.getDay()+6)%7;x.setDate(x.getDate()-wd);return x}
function naturalWeek(offset=0){const start=mondayOfKey();start.setDate(start.getDate()-offset*7);return Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return d.toLocaleDateString('en-CA')})}
function weekSummary(){let push=0,complete=0,protein=0;for(const k of naturalWeek()){const st=dayStatus(k);push+=st.pushTotal;if(st.protein)protein++;if(st.both)complete++}return {push,avg:Math.round(push/7),protein,complete}}
function weeklyStreak(){let weeks=0,start=naturalWeek(0).filter(k=>dayStatus(k).both).length>=5?0:1;for(let w=start;w<52;w++){const ok=naturalWeek(w).filter(k=>dayStatus(k).both).length;if(ok>=5)weeks++;else break}return weeks}
function bestWeek(){let best={complete:0,push:0,label:'—'};for(let w=0;w<104;w++){const ks=naturalWeek(w);let complete=0,push=0;for(const k of ks){const st=dayStatus(k);if(st.both)complete++;push+=st.pushTotal}if(complete>best.complete||(complete===best.complete&&push>best.push)){best={complete,push,label:keyDate(ks[0]).toLocaleDateString('es',{day:'numeric',month:'short'})}}}return best}
function weightTrend(){const xs=s.checkins.filter(x=>n(x.weight)).slice(-7);if(!xs.length)return null;return xs.reduce((a,x)=>a+n(x.weight),0)/xs.length}
function maintenanceEstimate(){const cs=s.checkins.filter(x=>n(x.weight)&&x.date).sort((a,b)=>a.date.localeCompare(b.date));if(cs.length<3)return null;const b=cs.at(-1),end=keyDate(b.date),eligible=cs.filter(x=>(end-keyDate(x.date))/86400000>=14);if(!eligible.length)return null;const a=eligible.at(-1),start=keyDate(a.date),days=Math.round((end-start)/86400000);const windowCs=cs.filter(x=>x.date>=a.date&&x.date<=b.date);if(windowCs.length<3)return null;let kcal=0,logged=0;for(let i=0;i<days;i++){const k=shiftKey(a.date,i),t=dayTotals(s.days[k]||{meals:[]});if(t.kcal>=500){kcal+=t.kcal;logged++}}const coverage=logged/Math.max(1,days);if(coverage<.8)return null;const xs=windowCs.map(x=>(keyDate(x.date)-start)/86400000),ys=windowCs.map(x=>n(x.weight)),xm=xs.reduce((q,x)=>q+x,0)/xs.length,ym=ys.reduce((q,y)=>q+y,0)/ys.length,den=xs.reduce((q,x)=>q+(x-xm)**2,0);if(!den)return null;const slope=xs.reduce((q,x,i)=>q+(x-xm)*(ys[i]-ym),0)/den,avg=kcal/logged,est=avg-(slope*7700);if(!Number.isFinite(est)||est<1200||est>4500)return null;return {kcal:Math.round(est/10)*10,days,coverage:Math.round(coverage*100),delta:+(ys.at(-1)-ys[0]).toFixed(1),weights:windowCs.length}}
function monthReport(){const key=today(),base=new Date(key+'T12:00'),y=base.getFullYear(),m=base.getMonth(),days=new Date(y,m+1,0).getDate();let push=0,protein=0,complete=0,kcal=0,logged=0;for(let i=1;i<=days;i++){const k=new Date(y,m,i).toLocaleDateString('en-CA');if(k>key)break;const st=dayStatus(k),t=dayTotals(s.days[k]||{meals:[]});push+=st.pushTotal;if(st.protein)protein++;if(st.both)complete++;if(t.kcal>0){kcal+=t.kcal;logged++}}const cs=s.checkins.filter(x=>x.date?.slice(0,7)===key.slice(0,7)&&n(x.weight));const wd=cs.length>1?+(n(cs.at(-1).weight)-n(cs[0].weight)).toFixed(1):null;return {push,protein,complete,avgPush:Math.round(push/Math.max(1,new Date(key+'T12:00').getDate())),avgKcal:logged?Math.round(kcal/logged):0,weightDelta:wd}}
function recoveryMessage(k=today()){const h=healthDay(k),sleep=n(h.sleepMin);if(!sleep)return'';let load=0;for(let i=1;i<=3;i++){const d=new Date(k+'T12:00');d.setDate(d.getDate()-i);const dk=d.toLocaleDateString('en-CA'),hh=healthDay(dk);load+=n(hh.exerciseMin)+exerciseTotal('push',dk)/4}if(sleep<330)return '😴 Poco sueño. Hoy tómatelo con calma, papá.';if(sleep<390&&load>120)return 'Vienes cargado y has dormido poco. Recuperar también cuenta.';if(sleep>=450&&load<100)return '🔥 Buen sueño y carga controlada. HOY SE ENTRENA, PAPÁ.';return sleep>=420?'Buen sueño. Dale loco, pero escucha al cuerpo.':'Sueño justito. Entrena con cabeza.'}
function dayVerdict(k){const st=dayStatus(k),h=healthDay(k),t=dayTotals(s.days[k]||{meals:[]}),sleep=n(h.sleepMin);if(st.both&&sleep>=420)return 'DÍA REDONDO, PAPÁ 🔥';if(st.both)return 'OBJETIVOS HECHOS. VAMOOOS.';if(st.protein&&!st.push)return 'Proteína hecha. Día de descanso si tocaba.';if(st.push&&!st.protein)return 'Entreno hecho. Ojo con cerrar la proteína.';if(t.kcal||st.pushTotal||h.steps)return 'Día registrado. Mañana seguimos, loco.';return 'Sin presión: si hoy tocaba descanso, descanso.'}
async function dailySummary(k=today()){const d=s.days[k]||{meals:[],pushEvents:[],pullEvents:[],health:{}},st=dayStatus(k),t=dayTotals(d),h=healthDay(k),sleep=h.sleepMin?`${Math.floor(h.sleepMin/60)} h ${Math.round(h.sleepMin%60)} min`:'—';const imgs=(d.meals||[]).filter(m=>m.photoRef).map(m=>`<img data-photo-ref="${esc(m.photoRef)}" alt="">`).join('');modal(`<button class="back" data-act="close">‹ Volver</button><h2>Resumen · ${new Date(k+'T12:00').toLocaleDateString('es',{day:'numeric',month:'long'})}</h2><div class="dayDetail"><div><span>Comida</span><b>${Math.round(t.kcal)} kcal · ${Math.round(t.p)} g proteína</b></div><div><span>Flexiones</span><b>${st.pushTotal}</b></div><div><span>Dominadas</span><b>${exerciseTotal('pull',k)}</b></div><div><span>Pasos</span><b>${Math.round(n(h.steps)).toLocaleString()}</b></div><div><span>Actividad</span><b>${Math.round(n(h.activeKcal)||manualActivityKcal(k))} kcal</b></div><div><span>Sueño</span><b>${sleep}</b></div></div>${(d.pushEvents?.length||d.pullEvents?.length)?`<div class="foodSectionTitle">ENTRENAMIENTO</div><div class="meal-list">${[...(d.pushEvents||[]).map(e=>({...e,kind:'push'})),...(d.pullEvents||[]).map(e=>({...e,kind:'pull'}))].sort((a,b)=>String(a.at).localeCompare(String(b.at))).map(e=>`<div class="meal"><div><b>${e.kind==='push'?'Flexiones':'Dominadas'}</b><small>+${Math.round(n(e.amount))}</small></div><button class="del" data-summaryex="${e.id}" data-summarykind="${e.kind}" data-summarykey="${k}">×</button></div>`).join('')}</div>`:''}${d.meals?.length?`<div class="foodSectionTitle">COMIDAS</div><div class="meal-list">${d.meals.map(m=>`<div class="meal"><div><b>${esc(m.name)}</b><small>${Math.round(m.kcal)} kcal · Proteína ${Math.round(m.p)} g · Carbohidratos ${Math.round(m.c)} g · Grasa ${Math.round(m.f)} g</small></div><button class="del" data-summarymeal="${m.id}" data-summarykey="${k}">×</button></div>`).join('')}</div>`:''}${imgs?`<div class="foodSectionTitle">FOTOS DE COMIDA</div><div class="dailyPhotos">${imgs}</div>`:''}${recoveryMessage(k)?`<div class="recoveryNote">${recoveryMessage(k)}</div>`:''}<div class="dayVerdict">${dayVerdict(k)}</div><p class="note">Los datos del reloj aparecerán aquí automáticamente cuando conectemos Apple Health.</p>`);document.querySelectorAll('[data-summarymeal]').forEach(b=>b.onclick=()=>{if(!confirm('¿Eliminar esta comida?'))return;const d=day(b.dataset.summarykey),removed=d.meals.find(m=>m.id===b.dataset.summarymeal),prev=[...d.meals];d.meals=d.meals.filter(m=>m.id!==b.dataset.summarymeal);if(!save()){d.meals=prev;return}if(removed?.photoRef)photoDelete(removed.photoRef).catch(()=>{});dailySummary(b.dataset.summarykey)});document.querySelectorAll('[data-summaryex]').forEach(b=>b.onclick=()=>{if(!confirm('¿Eliminar este entrenamiento?'))return;const d=day(b.dataset.summarykey),prop=b.dataset.summarykind+'Events',prev=[...d[prop]];d[prop]=d[prop].filter(e=>e.id!==b.dataset.summaryex);if(!save()){d[prop]=prev;return}dailySummary(b.dataset.summarykey)});bindSheet();await hydratePhotoImages(document.querySelector('#sheet'))}
function calendarHTML(){const currentKey=today(),now=new Date(currentKey+'T12:00'),y=now.getFullYear(),m=now.getMonth(),first=new Date(y,m,1),days=new Date(y,m+1,0).getDate(),offset=(first.getDay()+6)%7;let cells='<div class="calHead">'+['L','M','X','J','V','S','D'].map(x=>`<span>${x}</span>`).join('')+'</div><div class="calGrid">';for(let i=0;i<offset;i++)cells+='<span></span>';for(let d=1;d<=days;d++){const k=new Date(y,m,d).toLocaleDateString('en-CA'),st=dayStatus(k),cls=(st.both?'done':(st.push||st.protein?'half':''))+(k===currentKey?' current':'');cells+=`<button class="calDay ${cls.trim()}" data-day="${k}" aria-current="${k===currentKey?'date':'false'}"><b>${d}</b><i>${st.both?'✓':(st.push||st.protein?'•':'')}</i></button>`}return cells+'</div>'}
function globalPlus(){modal(`<h2>Añadir</h2><button class="primary" data-act="food">＋ Comida</button><button class="secondary" data-act="customPush">＋ Flexiones</button><button class="secondary" data-act="customPull">＋ Dominadas</button><button class="secondary" data-act="checkin">＋ Peso / check-in</button>`);bindSheet()}
