function compactHealthStats(){const h=healthDay(),c=lastCheckin(),weight=n(h.weight)||n(h.weightKg)||n(c?.weight),sleep=n(h.sleepMin),cards=[['PASOS',h.steps?Math.round(n(h.steps)).toLocaleString('es-ES'):'—','blue'],['ACTIVIDAD',n(h.activeKcal)>0?Math.round(n(h.activeKcal))+' kcal':'—','orange'],['SUEÑO',sleep?Math.floor(sleep/60)+'h '+String(Math.round(sleep%60)).padStart(2,'0'):'—','purple'],['PESO',weight?weight.toFixed(1)+' kg':'—','green']];return `<button class="healthStats" data-act="healthStatus" aria-label="Ver estadísticas de Apple Salud">${cards.map(([label,val,color])=>`<span class="healthMini ${color}"><strong>${val}</strong><small>${label}</small></span>`).join('')}</button><div class="healthHint">${h.updatedAt?'Apple Salud · hoy (00:00–23:59) · sincronizado':'Apple Salud · hoy (00:00–23:59) · pendiente de sincronizar'}</div>`}
function healthSummary(){const h=healthDay(),has=h.source||h.steps||h.sleepMin||h.exerciseMin||h.weight||h.bodyFat;if(has){const sleep=h.sleepMin?`${Math.floor(h.sleepMin/60)} h ${Math.round(h.sleepMin%60)} min`:'—',body=h.weight?` · ⚖️ ${n(h.weight).toFixed(1)} kg${h.bodyFat?' · '+n(h.bodyFat).toFixed(1)+'% grasa':''}`:'';return `<button class="healthCard" data-act="healthStatus"><div><b>APPLE SALUD</b><span>${Math.round(n(h.steps)).toLocaleString()} pasos · 🔥 ${Math.round(n(h.activeKcal))} kcal${body}</span><small>Sueño ${sleep}${h.updatedAt?' · sincronizado':''}</small></div><strong>›</strong></button>`}return `<button class="healthCard pending" data-act="healthStatus"><div><b>APPLE SALUD preparado</b><span>iPhone / Xiaomi / Zepp → Salud → SU SU</span><small>Pendiente ejecutar el Atajo</small></div><strong>›</strong></button>`}
function healthStatus(){const h=healthDay();modal(`<h2>Apple Salud</h2><div class="dayDetail"><div><span>Estado</span><b>${s.healthSync.connected?'Conectado ✓':'Preparado · pendiente Atajo'}</b></div><div><span>Peso</span><b>${(h.weight||h.weightKg)?n(h.weight||h.weightKg).toFixed(1)+' kg':'—'}</b></div><div><span>Grasa corporal</span><b>${h.bodyFat?n(h.bodyFat).toFixed(1)+'%':'—'}</b></div><div><span>IMC</span><b>${h.bmi?n(h.bmi).toFixed(1):'—'}</b></div><div><span>Pasos</span><b>${Math.round(n(h.steps)).toLocaleString()}</b></div><div><span>Kcal en reposo</span><b>${n(h.restingKcal)?Math.round(n(h.restingKcal)):'—'}</b></div><div><span>Kcal activas</span><b>${Math.round(n(h.activeKcal))}</b></div><div><span>Distancia</span><b>${n(h.distanceKm)?n(h.distanceKm).toFixed(2)+' km':'—'}</b></div><div><span>Ejercicio</span><b>${Math.round(n(h.exerciseMin))} min</b></div><div><span>Sueño</span><b>${h.sleepMin?Math.floor(h.sleepMin/60)+' h '+Math.round(h.sleepMin%60)+' min':'—'}</b></div><div><span>FC reposo</span><b>${h.restingHr?Math.round(h.restingHr)+' bpm':'—'}</b></div></div><p class="note">Los datos llegan desde Apple Salud mediante el Atajo SU SU. Repetir la sincronización del mismo día actualiza los valores; no los suma, así evitamos duplicados.</p><button class="secondary" data-act="close">Cerrar</button>`);bindSheet()}
