function metricValue(type,k){if(type==='push')return (s.days[k]?.pushEvents||[]).reduce((a,e)=>a+n(e.amount),0);if(type==='pull')return (s.days[k]?.pullEvents||[]).reduce((a,e)=>a+n(e.amount),0);if(type==='weight'&&n(s.days[k]?.health?.weight))return n(s.days[k].health.weight);const c=s.checkins.find(x=>x.date===k&&n(x[type]));return c?n(c[type]):null}
