function chart(data){const valid=data.map((x,i)=>({...x,i})).filter(x=>x.v!==null&&x.v!==undefined&&Number.isFinite(Number(x.v))&&(metric==='weight'||metric==='waist'||Number(x.v)>0));if(!valid.length)return `<div class="chartEmpty">Todavía no hay suficientes datos.</div>`;const vals=valid.map(x=>Number(x.v)),min=Math.min(...vals),max=Math.max(...vals),span=Math.max(1,max-min),pts=valid.map(x=>`${x.i/(data.length-1||1)*100},${155-(Number(x.v)-min)/span*125}`).join(' ');const dots=valid.map(x=>`<circle cx="${x.i/(data.length-1||1)*100}" cy="${155-(Number(x.v)-min)/span*125}" r="2.1" fill="#111" vector-effect="non-scaling-stroke"/>`).join('');return `<svg class="chart" viewBox="0 0 100 180" preserveAspectRatio="none"><line x1="0" y1="155" x2="100" y2="155" stroke="#eee"/><polyline points="${pts}" fill="none" stroke="#111" stroke-width="2" vector-effect="non-scaling-stroke" stroke-linecap="round" stroke-linejoin="round"/>${dots}</svg>`}
function progressView(){const avg=pushAvg(),all=Object.keys(s.days),mr=monthReport(),maint=maintenanceEstimate(),prPush=Math.max(0,...all.map(k=>metricValue('push',k))),prPull=Math.max(0,...all.map(k=>metricValue('pull',k))),last=s.checkins.at(-1)||{},photos=s.checkins.reduce((a,c)=>a+(c.photos?.length||0),0),ws=weekSummary(),trend=weightTrend(),wstreak=weeklyStreak(),bw=bestWeek();return layout(`<section class="progressHero"><div class="number">${avg}</div><div class="label">FLEXIONES / DÍA ESTE MES</div><div class="progressSub">Media 7 días ${last7PushAvg()} · ${wstreak?`🔥 ${wstreak} semana${wstreak===1?'':'s'}`:'empieza tu racha'}</div></section><div class="weekCard"><div class="sectionhead"><h2>ESTA SEMANA</h2><span>${ws.complete}/7 completos</span></div><div class="weekStats"><div><b>${ws.push}</b><span>flexiones · ${ws.avg}/día</span></div><div><b>${ws.protein}/7</b><span>proteína</span></div><div><b>${ws.complete}/7</b><span>doble objetivo</span></div></div><div class="weekMessage">${ws.complete>=5?'🔥 BUENA SEMANA, PAPÁ':ws.complete>=3?'VAMOS PAPÁ · A POR 5/7':'DALE LOCOOO · TODAVÍA HAY SEMANA'}</div></div><div class="monthCard"><div class="sectionhead"><h2>ESTE MES</h2><span>${mr.complete} días completos</span></div><div class="weekStats"><div><b>${mr.push}</b><span>flexiones · ${mr.avgPush}/día</span></div><div><b>${mr.protein}</b><span>días proteína</span></div><div><b>${mr.avgKcal||"—"}</b><span>kcal/día registradas</span></div></div>${mr.weightDelta!==null?`<div class="monthWeight">Peso ${mr.weightDelta>0?"+":""}${mr.weightDelta} kg este mes</div>`:""}</div>${maint?`<div class="maintenanceCard"><span>MANTENIMIENTO APRENDIDO</span><strong>≈ ${maint.kcal.toLocaleString()} kcal/día</strong><small>Estimación con ${maint.days} días · ${maint.coverage}% de días con comida registrada. No cambia tu objetivo automáticamente.</small></div>`:`<div class="maintenanceCard pending"><span>MANTENIMIENTO APRENDIDO</span><strong>Aprendiendo…</strong><small>Necesito al menos 14 días entre pesos y comida registrada en ≥80% de los días.</small></div>`}<div class="sectionhead calendarHead"><h2>${new Date(today()+'T12:00').toLocaleDateString('es',{month:'long',year:'numeric'}).toUpperCase()}</h2><span>✓ flexiones + proteína</span></div><div class="calendar">${calendarHTML()}</div><div class="metricTabs"><button data-metric="push" class="${metric==='push'?'active':''}">Flex.</button><button data-metric="pull" class="${metric==='pull'?'active':''}">Dom.</button><button data-metric="weight" class="${metric==='weight'?'active':''}">Peso</button><button data-metric="waist" class="${metric==='waist'?'active':''}">Cintura</button></div><div class="tabs"><button class="${period===7?'active':''}" data-period="7">7D</button><button class="${period===30?'active':''}" data-period="30">30D</button><button class="${period===90?'active':''}" data-period="90">3M</button><button class="${period===365?'active':''}" data-period="365">1A</button></div>${chart(series(metric,period))}<div class="sectionhead"><h2>RÉCORDS</h2><span>mejor día</span></div><div class="cards"><div class="card"><span>Flexiones</span><strong>${prPush}</strong></div><div class="card"><span>Dominadas</span><strong>${prPull}</strong></div><div class="card"><span>Mejor semana</span><strong>${bw.complete}/7</strong><small>${bw.push} flex. · desde ${bw.label}</small></div></div><div class="sectionhead bodyhead"><h2>CUERPO</h2><span>tendencia</span></div><div class="bodySummary"><div><span>Peso actual</span><strong>${last.weight?last.weight+' kg':'—'}</strong></div><div><span>Tendencia</span><strong>${trend?trend.toFixed(1)+' kg':'—'}</strong></div></div><button class="primary" data-act="checkin">Check-in semanal</button>${s.checkins.filter(c=>c.photos?.length).length>1?'<button class="secondary" data-act="compare">Antes ↔ Ahora</button>':''}<button class="quietRow" data-act="history"><span>Historial corporal</span><span>${s.checkins.length} check-ins · ${photos} fotos ›</span></button>`)}
function render(){document.querySelector('#app').innerHTML=view==='today'?todayView():progressView();bind()}
let sheetDirty=false,sheetGestureBound=false;
function modal(html){const sh=document.querySelector('#sheet'),m=document.querySelector('#modal');sheetDirty=false;sh.innerHTML=`<button class="sheetClose" type="button" aria-label="Cerrar">×</button>${html}`;m.classList.add('show');const protect=()=>!!sh.querySelector('#checkForm')&&sheetDirty;sh.querySelector('.sheetClose').onclick=()=>requestCloseSheet(protect());sh.querySelectorAll('#checkForm input,#checkForm textarea,#checkForm select').forEach(el=>{el.addEventListener('input',()=>sheetDirty=true);el.addEventListener('change',()=>sheetDirty=true)});bindSheetGestures()}
function requestCloseSheet(protect=false){if(protect&&!confirm('Tienes un check-in sin guardar. ¿Cerrar igualmente?'))return false;close();return true}
function close(){sheetDirty=false;const m=document.querySelector('#modal');m.classList.remove('show');m.querySelector('.sheet')?.style.removeProperty('transform');m.querySelector('.sheet')?.style.removeProperty('transition');targetDay=null;if(sessionStorage.getItem('susu-reload-pending')==='1'){sessionStorage.removeItem('susu-reload-pending');location.reload()}}
function bindSheetGestures(){if(sheetGestureBound)return;sheetGestureBound=true;const m=document.querySelector('#modal'),sh=m.querySelector('.sheet');m.addEventListener('click',e=>{if(e.target===m)requestCloseSheet(!!document.querySelector('#checkForm')&&sheetDirty)});let sy=0,last=0,drag=false;sh.addEventListener('touchstart',e=>{if(e.touches.length!==1)return;sy=last=e.touches[0].clientY;drag=sh.scrollTop<=1},{passive:true});sh.addEventListener('touchmove',e=>{if(!drag)return;last=e.touches[0].clientY;const dy=last-sy;if(dy<=0){sh.style.transform='';return}if(sh.scrollTop>1){drag=false;sh.style.transform='';return}sh.style.transition='none';sh.style.transform=`translateY(${Math.min(dy,180)}px)`},{passive:true});sh.addEventListener('touchend',()=>{if(!drag)return;const dy=last-sy;drag=false;sh.style.transition='transform .18s ease';if(dy>90){sh.style.transform='translateY(110%)';setTimeout(()=>requestCloseSheet(!!document.querySelector('#checkForm')&&sheetDirty),120)}else sh.style.transform='translateY(0)';setTimeout(()=>{if(m.classList.contains('show')){sh.style.removeProperty('transition');sh.style.removeProperty('transform')}},220)},{passive:true})}
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),900)}
function logExercise(type,amount){amount=Math.max(1,Math.round(n(amount)));const k=activeDay(),list=day(k)[type+'Events'];list.push({id:id(),amount,at:k===today()?new Date().toISOString():`${k}T12:00:00`});if(!save()){list.pop();return}const total=exerciseTotal(type,k),prevMax=Math.max(0,...Object.keys(s.days).filter(x=>x!==k).map(x=>metricValue(type,x)||0));targetDay=null;render();toast(total>prevMax&&prevMax>0?`🏆 NUEVO RÉCORD · ${total} · PAPÁ SE HA CALENTADO`:`+${amount} · ${type==='push'?motivation(total,s.profile.pushGoal):'hoy '+total}`)}
function undoExercise(type){const a=day()[type+'Events'];if(a?.length){const e=a.pop();if(!save()){a.push(e);return}render();toast(`−${e.amount} · hoy ${exerciseTotal(type)}`)}}
function recentMeals(){const nowH=new Date().getHours(),all=Object.values(s.days).flatMap(d=>d.meals||[]),groups=new Map();for(const m of all){const k=(m.name||'').toLowerCase();if(!k)continue;const h=m.at?new Date(m.at).getHours():12,dist=Math.min(Math.abs(h-nowH),24-Math.abs(h-nowH)),score=20-dist+(m.at?Math.max(0,7-(Date.now()-new Date(m.at))/86400000):0);const g=groups.get(k)||{meal:m,score:0,count:0,last:''};g.score+=score;g.count++;if(String(m.at||'')>g.last){g.meal=m;g.last=String(m.at||'')}groups.set(k,g)}return [...groups.values()].sort((a,b)=>(b.score+b.count*3)-(a.score+a.count*3)).slice(0,5).map(x=>x.meal)}
function isFavorite(name){return (s.favorites||[]).some(x=>x.name.toLowerCase()===String(name||'').toLowerCase())}
function toggleFavorite(meal){const k=String(meal.name||'').toLowerCase(),i=(s.favorites||[]).findIndex(x=>x.name.toLowerCase()===k);if(i>=0){s.favorites.splice(i,1);toast('Quitado de favoritos')}else{s.favorites=s.favorites||[];s.favorites.unshift({name:meal.name,kcal:n(meal.kcal),p:n(meal.p),c:n(meal.c),f:n(meal.f)});s.favorites=s.favorites.slice(0,30);toast('⭐ Guardado en favoritos')}save();render()}
function foodModal(){const recent=recentMeals().slice(0,3),fav=(s.favorites||[]).slice(0,3);modal(`<div class="foodCompact"><h2>Añadir comida</h2><div class="smartFoodSearch"><input class="input foodSearchTop" id="foodSearch" placeholder="¿Qué has comido?" autocomplete="off" autofocus><button type="button" class="micInline" id="foodMic" aria-label="Dictar">🎙️</button><button type="button" class="sparkInline" id="interpretFood" aria-label="Interpretar" disabled>✨</button></div><div class="searchResults compactResults" id="foodResults"></div><div class="foodQuickActions bigFoodActions"><button data-act="photoSource">📷<span>Foto</span></button><button data-act="barcode">▦<span>Código</span></button><button data-act="labelScan">▤<span>Etiqueta</span></button><button id="showFavorites">★<span>Favoritos</span></button><button data-act="savedMeals">🥘<span>Mis platos</span></button></div><div id="foodSmartLists">${fav.length?`<div class="foodSectionTitle">HABITUALES</div><div class="foodChips">${fav.map((m,i)=>`<button data-favorite="${i}">★ ${esc(m.name)}</button>`).join('')}</div>`:''}${recent.length?`<div class="foodSectionTitle">RECIENTES</div><div class="foodChips">${recent.map((m,i)=>`<button data-recent="${i}">${esc(m.name)}</button>`).join('')}</div>`:''}</div></div>`);const q=document.querySelector('#foodSearch'),ib=document.querySelector('#interpretFood'),lists=document.querySelector('#foodSmartLists');const sync=()=>{const v=q.value.trim();ib.disabled=!v;lists.style.display=v?'none':'';foodResults(v)};q.oninput=sync;ib.onclick=()=>{const v=q.value.trim();if(v)analyzeTextFood(v)};document.querySelector('#foodMic').onclick=()=>startDictationInto(q,sync);document.querySelector('#showFavorites').onclick=()=>{q.value='';sync();document.querySelector('#foodSmartLists')?.scrollIntoView({behavior:'smooth'})};document.querySelectorAll('[data-recent]').forEach(b=>b.onclick=()=>{const m=recent[+b.dataset.recent];addMeal({...m,id:id(),at:new Date().toISOString(),source:'recent'})});document.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>{const m=fav[+b.dataset.favorite];addMeal({...m,id:id(),at:new Date().toISOString(),source:'favorite'})});bindSheet();setTimeout(()=>q.focus(),80)}
function foodResults(q){const el=document.querySelector('#foodResults');if(!el)return;const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();const raw=norm(q),term=raw.replace(/^\s*\d+(?:[.,]\d+)?\s*(?:g|gr|gramos?|kg|ml|l|unidad(?:es)?|ud|x)?\s+(?:de\s+)?/,'').trim()||raw;if(!term){el.innerHTML='';return}const seen=new Set(),results=[];const add=(kind,f,index,priority)=>{const name=norm(f.name),aliases=norm(f.aliases||'');if(!(name.includes(term)||aliases.includes(term))||seen.has(name))return;seen.add(name);results.push({kind,f,index,priority,starts:name.startsWith(term)?1:0})};(s.learnedFoods||[]).forEach((f,i)=>add('learned',f,i,4));(s.favorites||[]).forEach((f,i)=>add('favorite',f,i,5));ingredients.forEach((f,i)=>add('basic',f,i,2));foods.forEach((f,i)=>add('food',f,i,1));results.sort((a,b)=>b.starts-a.starts||b.priority-a.priority||a.f.name.length-b.f.name.length);const top=results.slice(0,3);el.innerHTML=top.length?top.map(r=>`<button data-resultkind="${r.kind}" data-resultindex="${r.index}"><b>${r.kind==='favorite'?'★ ':''}${esc(r.f.name)}</b><small>${Math.round(n(r.f.kcal))} kcal${r.kind==='basic'?` · ${n(r.f.p)}g proteína / 100 ${r.f.unit||'g'}`:` · ${Math.round(n(r.f.p))}g proteína`}</small></button>`).join(''):`<div class="emptySearch emptySearchStack"><span>No está en tu biblioteca.</span><button class="miniManual interpretMissing" id="interpretMissing">✨ Interpretar con SU SU</button><button class="miniManual" data-act="manual">Añadir manualmente</button></div>`;const im=document.querySelector('#interpretMissing');if(im)im.onclick=()=>analyzeTextFood(q);document.querySelectorAll('[data-resultkind]').forEach(b=>b.onclick=()=>{const kind=b.dataset.resultkind,i=+b.dataset.resultindex;if(kind==='basic')return foodAmount(ingredients[i]);const f=kind==='learned'?s.learnedFoods[i]:kind==='favorite'?s.favorites[i]:foods[i];addMeal({...f,id:id(),at:new Date().toISOString(),source:kind})});bindSheet()}
function foodAmount(x){const unit=x.unit||'g';modal(`<button class="back" data-act="food">‹ Buscar</button><h2>${esc(x.name)}</h2><form id="foodAmountForm"><label class="fieldLabel">Cantidad en ${unit}</label><input class="input" name="amount" type="number" inputmode="decimal" min="1" step="1" placeholder="ej. ${unit==='ml'?'350':'200'}" autofocus required><p class="note">Por 100 ${unit}: ${x.kcal} kcal · ${x.p}g P · ${x.c}g C · ${x.f}g G</p><button class="primary">${activeDay()===today()?'Añadir a hoy':'Añadir al '+new Date(activeDay()+'T12:00').toLocaleDateString('es',{day:'numeric',month:'short'})}</button><button type="button" class="secondary" data-act="food">Cancelar</button></form>`);document.querySelector('#foodAmountForm').onsubmit=e=>{e.preventDefault();const a=n(new FormData(e.target).get('amount')),r=a/100;if(a>0)addMeal({id:id(),name:`${x.name} · ${a} ${unit}`,kcal:Math.round(x.kcal*r),p:+(x.p*r).toFixed(1),c:+(x.c*r).toFixed(1),f:+(x.f*r).toFixed(1),source:'database',at:new Date().toISOString()})};bindSheet()}
function activeDay(){return targetDay||today()}
function addMeal(meal){const d=day(activeDay());d.meals.push(meal);s.foodHistory=[{name:meal.name,at:meal.at||new Date().toISOString()},...(s.foodHistory||[])].slice(0,100);if(!save()){d.meals.pop();return}close();render();toast(`${Math.round(meal.kcal)} kcal añadidas`)}
function rememberCorrection(meal){if(!meal?.name)return;const item={name:meal.name,kcal:meal.kcal,p:meal.p,c:meal.c,f:meal.f};const i=(s.learnedFoods||[]).findIndex(x=>x.name.toLowerCase()===meal.name.toLowerCase());if(i>=0)s.learnedFoods[i]=item;else{s.learnedFoods=s.learnedFoods||[];s.learnedFoods.unshift(item);s.learnedFoods=s.learnedFoods.slice(0,50)}}
function manualForm(pref={}){modal(`${pref.ai?'<button class="back" data-act="food">‹ Volver</button>':'<button class="back" data-act="food">‹ Buscar</button>'}<h2>${pref.ai?'Revisar estimación':'Comida manual'}</h2>${pref.image?`<img class="aiPreview" src="${pref.image}">`:''}<form id="mealForm"><input class="input" name="name" placeholder="Comida" value="${esc(pref.name||'')}" required><div class="nutritionEdit"><label>CALORÍAS (kcal)<input class="input" name="kcal" type="number" step="1" placeholder="0" value="${pref.kcal??''}" required></label><label>PROTEÍNA (g)<input class="input" name="p" type="number" step=".1" placeholder="0" value="${pref.p??''}"></label><label>CARBOHIDRATOS (g)<input class="input" name="c" type="number" step=".1" placeholder="0" value="${pref.c??''}"></label><label>GRASA (g)<input class="input" name="f" type="number" step=".1" placeholder="0" value="${pref.f??''}"></label></div>${pref.ai?'<p class="note">Estimación de IA. Cambia el nombre o cualquier valor antes de guardar. SU SU recordará tu corrección.</p>':''}<button class="primary">${activeDay()===today()?'Añadir a hoy':'Añadir al '+new Date(activeDay()+'T12:00').toLocaleDateString('es',{day:'numeric',month:'short'})}</button>${pref.ai?'<button type="button" class="secondary" data-act="photoSource">Otra foto</button>':''}<button type="button" class="secondary" data-act="food">Cancelar</button></form>`);document.querySelector('#mealForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),meal={id:id(),name:f.get('name').trim(),kcal:n(f.get('kcal')),p:n(f.get('p')),c:n(f.get('c')),f:n(f.get('f')),source:pref.ai?'ai-corrected':'manual',at:new Date().toISOString()};if(pref.image){try{meal.photoRef=await photoPut(pref.image)}catch{}}if(pref.ai)rememberCorrection(meal);addMeal(meal)};bindSheet()}
let draftPlate={name:'',items:[]};
function plateTotals(){return draftPlate.items.reduce((a,x)=>({kcal:a.kcal+x.kcal*x.g/100,p:a.p+x.p*x.g/100,c:a.c+x.c*x.g/100,f:a.f+x.f*x.g/100}),{kcal:0,p:0,c:0,f:0})}
function plateBuilder(reset=true){if(reset)draftPlate={name:'',items:[]};renderPlateBuilder()}
function renderPlateBuilder(){const t=plateTotals();modal(`<h2>Crear plato</h2><input class="input" id="plateName" placeholder="Nombre del plato · ej. Pasta con pollo" value="${esc(draftPlate.name)}"><div class="plateTotals"><strong>${Math.round(t.kcal)} kcal</strong><span>Proteína ${Math.round(t.p)} g · Carbohidratos ${Math.round(t.c)} g · Grasa ${Math.round(t.f)} g</span></div>${draftPlate.items.length?`<div class="ingredientList">${draftPlate.items.map((x,i)=>`<div class="ingredientRow"><div><b>${esc(x.name)}</b><small>${x.g} g · ${Math.round(x.kcal*x.g/100)} kcal</small></div><button data-removeingredient="${i}" aria-label="Eliminar">×</button></div>`).join('')}</div>`:''}<input class="input" id="ingredientSearch" placeholder="Buscar ingrediente · pollo, pasta, parmesano…"><div class="searchResults" id="ingredientResults"></div><button class="secondary" data-act="customIngredient">＋ Ingrediente con valores propios</button>${draftPlate.items.length?'<button class="primary" data-act="finishPlate">Terminar plato</button>':''}<p class="note">Valores por 100 g. Elige bien crudo/cocinado cuando aparezcan ambas opciones.</p>`);const pn=document.querySelector('#plateName');pn.oninput=()=>draftPlate.name=pn.value;const q=document.querySelector('#ingredientSearch');q.oninput=()=>ingredientResults(q.value);ingredientResults('');document.querySelectorAll('[data-removeingredient]').forEach(b=>b.onclick=()=>{draftPlate.items.splice(+b.dataset.removeingredient,1);renderPlateBuilder()});bindSheet()}
function ingredientResults(q){const el=document.querySelector('#ingredientResults');if(!el)return;const term=q.trim().toLowerCase();const r=(term?ingredients.filter(x=>x.name.toLowerCase().includes(term)):ingredients.slice(0,7)).slice(0,10);el.innerHTML=r.map((x,i)=>`<button data-ing="${ingredients.indexOf(x)}"><b>${esc(x.name)}</b><small>${x.kcal} kcal · ${x.p}g proteína / 100 g</small></button>`).join('');document.querySelectorAll('[data-ing]').forEach(b=>b.onclick=()=>ingredientAmount(ingredients[+b.dataset.ing]))}
function ingredientAmount(x){modal(`<button class="back" data-act="backPlate">‹ Plato</button><h2>${esc(x.name)}</h2><form id="ingredientAmountForm"><label class="fieldLabel">Cantidad en gramos</label><input class="input" name="g" type="number" inputmode="decimal" min="1" step="1" placeholder="ej. 200" autofocus required><p class="note">Por 100 g: ${x.kcal} kcal · ${x.p}g P · ${x.c}g C · ${x.f}g G</p><button class="primary">Añadir ingrediente</button></form>`);document.querySelector('#ingredientAmountForm').onsubmit=e=>{e.preventDefault();const g=n(new FormData(e.target).get('g'));if(g>0){draftPlate.items.push({...x,g});renderPlateBuilder()}};bindSheet()}
function customIngredient(){modal(`<button class="back" data-act="backPlate">‹ Plato</button><h2>Ingrediente personalizado</h2><form id="customIngForm"><input class="input" name="name" placeholder="Ingrediente" required><input class="input" name="g" type="number" inputmode="decimal" min="1" placeholder="Gramos que vas a usar" required><p class="note">Valores nutricionales por 100 g (mira la etiqueta del producto).</p><div class="formgrid"><input class="input" name="kcal" type="number" placeholder="kcal / 100g" required><input class="input" name="p" type="number" step=".1" placeholder="Proteína / 100g"><input class="input" name="c" type="number" step=".1" placeholder="Carbos / 100g"><input class="input" name="f" type="number" step=".1" placeholder="Grasa / 100g"></div><button class="primary">Añadir</button></form>`);document.querySelector('#customIngForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),g=n(f.get('g'));if(g>0){draftPlate.items.push({name:f.get('name'),g,kcal:n(f.get('kcal')),p:n(f.get('p')),c:n(f.get('c')),f:n(f.get('f'))});renderPlateBuilder()}};bindSheet()}
function finishPlate(){if(!draftPlate.items.length)return;const t=plateTotals(),name=(draftPlate.name||draftPlate.items.map(x=>x.name).slice(0,2).join(' + ')).trim();modal(`<h2>${esc(name)}</h2><div class="plateFinal"><strong>${Math.round(t.kcal)} kcal</strong><span>${Math.round(t.p)} g proteína · ${Math.round(t.c)} g carbos · ${Math.round(t.f)} g grasa</span></div><div class="ingredientSummary">${draftPlate.items.map(x=>`<span>${esc(x.name)} · ${x.g} g</span>`).join('')}</div><button class="primary" data-act="addPlateToday">Añadir a hoy</button><button class="secondary" data-act="saveAndAddPlate">Guardar plato + añadir</button><button class="secondary" data-act="backPlate">Editar ingredientes</button>`);bindSheet()}
function addDraftPlate(saveRecipe=false){const t=plateTotals(),name=(draftPlate.name||draftPlate.items.map(x=>x.name).slice(0,2).join(' + ')).trim(),meal={id:id(),name,kcal:Math.round(t.kcal),p:+t.p.toFixed(1),c:+t.c.toFixed(1),f:+t.f.toFixed(1),source:'builder',items:draftPlate.items.map(x=>({...x})),at:new Date().toISOString()};const d=day();d.meals.push(meal);if(saveRecipe&&!s.savedMeals.some(x=>x.name===name)){s.savedMeals.push({id:id(),name,items:draftPlate.items.map(x=>({...x,g:undefined})),amounts:draftPlate.items.map(x=>x.g)})}if(!save()){d.meals.pop();return}close();render();toast(saveRecipe?'Plato guardado y añadido':'Plato añadido')}
function savedMeals(){if(!s.savedMeals.length){foodModal();return}modal(`<h2>Mis platos</h2><div class="searchResults">${s.savedMeals.map(x=>`<button data-savedmeal="${x.id}"><b>${esc(x.name)}</b><small>${x.items.length} ingredientes</small></button>`).join('')}</div><button class="secondary" data-act="food">‹ Volver</button>`);document.querySelectorAll('[data-savedmeal]').forEach(b=>b.onclick=()=>{const x=s.savedMeals.find(v=>v.id===b.dataset.savedmeal);draftPlate={name:x.name,items:x.items.map((v,i)=>({...v,g:x.amounts?.[i]||100}))};renderPlateBuilder()});bindSheet()}
function settings(){modal(`<h2>Ajustes</h2><form id="settingsForm" class="settings"><label>Objetivo flexiones / día</label><input class="input" name="pushGoal" type="number" value="${s.profile.pushGoal}"><label>Metabolismo basal estimado (kcal)</label><input class="input" name="basalKcal" type="number" min="1000" max="3500" value="${s.profile.basalKcal||1834}"><label>Déficit diario deseado (kcal)</label><input class="input" name="deficitGoal" type="number" min="0" max="1000" value="${s.profile.deficitGoal??400}"><p class="note">Objetivo dinámico = reposo estimado + kcal activas de Apple Salud − déficit. Los pasos NO se suman aparte. Si Apple Salud envía energía en reposo, se usa esa cifra.</p><label>Proteína / día (g)</label><input class="input" name="proteinGoal" type="number" value="${s.profile.proteinGoal}"><label>Carbohidratos / día (g)</label><input class="input" name="carbGoal" type="number" value="${s.profile.carbGoal}"><label>Grasa / día (g)</label><input class="input" name="fatGoal" type="number" value="${s.profile.fatGoal}"><label>El día SU SU termina a</label><select class="input" name="dayCutoffHour"><option value="0">00:00</option><option value="1">01:00</option><option value="2">02:00</option><option value="3">03:00</option><option value="4">04:00</option><option value="5">05:00</option><option value="6">06:00</option></select><p class="note">Antes de esta hora, comidas, flexiones y dominadas cuentan para el día anterior. Los datos de Apple Salud (pasos, calorías y sueño) usan el día natural desde las 00:00.</p><label>Endpoint Gemini</label><input class="input" name="geminiEndpoint" value="${esc(s.profile.geminiEndpoint||'')}" placeholder="Lo configuraremos después"><p class="note">Nunca guardes la API key aquí. La clave irá como secreto en el Worker privado.</p><button class="primary">Guardar</button></form><button class="secondary" data-act="export">Exportar backup</button><button class="secondary" data-act="import">Importar backup</button>`);document.querySelector('[name=dayCutoffHour]').value=String(s.profile.dayCutoffHour??2);document.querySelector('#settingsForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);['pushGoal','kcalGoal','proteinGoal','carbGoal','fatGoal'].forEach(k=>s.profile[k]=Math.max(0,n(f.get(k))));s.profile.basalKcal=Math.max(1000,Math.min(3500,n(f.get('basalKcal'))||1834));s.profile.deficitGoal=Math.max(0,Math.min(1000,n(f.get('deficitGoal'))));s.profile.dayCutoffHour=Math.max(0,Math.min(23,n(f.get('dayCutoffHour'))));s.profile.geminiEndpoint=f.get('geminiEndpoint').trim();save();close();render()}}
async function compress(file,max=1000,q=.76){
 if(!file||!String(file.type||'').startsWith('image/'))throw Error('Archivo no válido');
 let img=null,revoke=null;
 try{
  if(typeof createImageBitmap==='function'){try{img=await createImageBitmap(file,{imageOrientation:'from-image'})}catch{img=null}}
  if(!img){const url=URL.createObjectURL(file);revoke=()=>URL.revokeObjectURL(url);img=await new Promise((resolve,reject)=>{const el=new Image();el.onload=()=>resolve(el);el.onerror=()=>reject(Error('No se pudo abrir la imagen'));el.src=url})}
  const w=img.width||img.naturalWidth,h=img.height||img.naturalHeight;if(!w||!h)throw Error('Imagen sin dimensiones');
  const scale=Math.min(1,max/Math.max(w,h)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(w*scale));c.height=Math.max(1,Math.round(h*scale));const ctx=c.getContext('2d');if(!ctx)throw Error('Canvas no disponible');ctx.drawImage(img,0,0,c.width,c.height);return c.toDataURL('image/jpeg',q)
 }finally{try{img?.close?.()}catch{}try{revoke?.()}catch{}}
}
function photoSourceModal(){modal(`<button class="back" data-act="food">‹ Volver</button><h2>Añadir foto</h2><p class="note">Elige cómo quieres añadir la foto de la comida.</p><div class="photoSourceActions"><button class="primary" data-act="camera">📷 Hacer foto</button><button class="secondary" data-act="gallery">🖼️ Elegir de galería</button></div>`);bindSheet()}
function photoContext(data){modal(`<button class="back" data-act="food">‹ Volver</button><h2>Foto de comida</h2><img class="aiPreview" src="${data}"><form id="photoContextForm"><textarea class="input describeBox" name="context" rows="3" placeholder="Opcional · ej. es pollo, hay 200 g de arroz, me comí la mitad…"></textarea><button class="primary">Analizar foto</button><button type="button" class="secondary" id="skipContext">Analizar sin contexto</button><button type="button" class="secondary" data-act="food">Cancelar</button></form>`);const form=document.querySelector('#photoContextForm');form.onsubmit=e=>{e.preventDefault();analyzeMeal(data,new FormData(form).get('context').trim())};document.querySelector('#skipContext').onclick=()=>analyzeMeal(data,'');bindSheet()}
async function analyzeMeal(data,context=''){if(!s.profile.geminiEndpoint){manualForm({image:data});return}modal(`<button class="back" data-act="food">‹ Volver</button><h2>Analizando…</h2><img class="aiPreview" src="${data}"><p class="note">${context?'Usando también tu contexto. ':''}Podrás cambiar todo antes de guardar.</p><button class="secondary" data-act="food">Cancelar</button>`);bindSheet();const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);try{const r=await fetch(s.profile.geminiEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({image:data,context}),signal:controller.signal});if(!r.ok)throw Error('HTTP '+r.status);const x=await r.json();if(!x||typeof x.name!=='string'||![x.kcal,x.protein_g,x.carbs_g,x.fat_g].every(v=>Number.isFinite(Number(v))&&Number(v)>=0))throw Error('Invalid AI response');manualForm({image:data,ai:true,name:x.name,kcal:n(x.kcal),p:n(x.protein_g),c:n(x.carbs_g),f:n(x.fat_g)})}catch(e){manualForm({image:data});toast('IA no disponible · entrada manual')}finally{clearTimeout(timer)}}
async function analyzeTextFood(text){if(!s.profile.geminiEndpoint){manualForm({name:text});return}modal(`<button class="back" data-act="describe">‹ Volver</button><h2>Interpretando…</h2><p class="note">${esc(text)}</p><button class="secondary" data-act="food">Cancelar</button>`);bindSheet();const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);try{const r=await fetch(s.profile.geminiEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text}),signal:controller.signal});if(!r.ok)throw Error('HTTP '+r.status);const x=await r.json();if(!x||typeof x.name!=='string'||![x.kcal,x.protein_g,x.carbs_g,x.fat_g].every(v=>Number.isFinite(Number(v))&&Number(v)>=0))throw Error('Invalid AI response');manualForm({ai:true,name:x.name,kcal:n(x.kcal),p:n(x.protein_g),c:n(x.carbs_g),f:n(x.fat_g)})}catch(e){manualForm({name:text});toast('No pude interpretarlo · revísalo manualmente')}finally{clearTimeout(timer)}}
function checkin(){modal(`<h2>Check-in semanal</h2><p class="checkinLead">Peso y cintura son obligatorios. Hazlo una vez cada 7 días para que SU SU pueda enseñarte tu evolución de verdad.</p><form id="checkForm"><label class="fieldLabel">PESO (kg) *</label><input class="input" name="weight" type="number" inputmode="decimal" min="30" max="300" step=".1" placeholder="Ej. 82.4" required><label class="fieldLabel">CINTURA (cm) *</label><input class="input" name="waist" type="number" inputmode="decimal" min="40" max="250" step=".1" placeholder="Ej. 86.5" required><details class="optional"><summary>Más medidas</summary><input class="input" name="chest" type="number" step=".1" placeholder="Pecho (cm)"><input class="input" name="arm" type="number" step=".1" placeholder="Brazo (cm)"></details><div class="checkPhotoGrid"><div class="checkPhotoActions"><label class="photoPicker">📷 Hacer foto<input id="checkCamera" type="file" accept="image/*" capture="environment" hidden></label><label class="photoPicker">🖼️ Galería<input id="checkGallery" type="file" accept="image/*" multiple hidden></label></div><div id="photoCount" class="note">Frontal, lateral y espalda · máximo 3 · opcionales</div></div><button class="primary">Guardar check-in</button></form><p class="note">Las fotos corporales se guardan en tu dispositivo y no se envían a Gemini.</p>`);let files=[];const refresh=()=>document.querySelector('#photoCount').textContent=files.length?`${files.length} foto${files.length===1?'':'s'} seleccionada${files.length===1?'':'s'} · máximo 3`:'Frontal, lateral y espalda · máximo 3 · opcionales';document.querySelector('#checkCamera').onchange=e=>{if(e.target.files[0]&&files.length<3)files.push(e.target.files[0]);e.target.value='';refresh()};document.querySelector('#checkGallery').onchange=e=>{files=[...files,...e.target.files].slice(0,3);e.target.value='';refresh()};document.querySelector('#checkForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),weight=n(f.get('weight')),waist=n(f.get('waist'));if(!(weight>=30&&weight<=300&&waist>=40&&waist<=250)){toast('Revisa peso y cintura');return}const photos=[];for(const file of files){const data=await compress(file,900,.7);try{photos.push(await photoPut(data))}catch{for(const ref of photos)try{await photoDelete(ref)}catch{}toast('No pude guardar las fotos');return}}const entry={id:id(),date:today(),at:new Date().toISOString(),weight,waist,chest:n(f.get('chest'))||null,arm:n(f.get('arm'))||null,photos};s.checkins.push(entry);if(!save()){s.checkins.pop();for(const ref of photos)try{await photoDelete(ref)}catch{}return}close();render();toast('Check-in semanal completado ✓')}}
function history(){if(!s.checkins.length){modal(`<h2>Historial corporal</h2><div class="empty">Aún no tienes check-ins.</div>`);return}modal(`<h2>Historial corporal</h2><div class="history">${[...s.checkins].reverse().map(c=>`<button class="historyItem" data-check="${c.id}"><div><b>${new Date(c.date+'T12:00').toLocaleDateString('es',{day:'numeric',month:'short',year:'numeric'})}</b><small>${c.weight?c.weight+' kg · ':''}${c.waist?c.waist+' cm cintura · ':''}${c.photos?.length||0} fotos</small></div><span>›</span></button>`).join('')}</div>${s.checkins.length>1?'<button class="secondary" data-act="compare">Comparar primero ↔ último</button>':''}`);document.querySelectorAll('[data-check]').forEach(b=>b.onclick=()=>checkDetail(b.dataset.check));bindSheet()}
async function checkDetail(cid){const c=s.checkins.find(x=>x.id===cid);if(!c)return;modal(`<button class="back" data-act="history">‹ Historial</button><h2>${new Date(c.date+'T12:00').toLocaleDateString('es',{day:'numeric',month:'long',year:'numeric'})}</h2><div class="bodySummary"><div><span>Peso</span><strong>${c.weight?c.weight+' kg':'—'}</strong></div><div><span>Cintura</span><strong>${c.waist?c.waist+' cm':'—'}</strong></div></div>${c.photos?.length?`<div class="privatePhotos">${c.photos.map(p=>`<img data-photo-ref="${esc(p)}">`).join('')}</div>`:'<div class="empty">Sin fotos en este check-in.</div>'}`);bindSheet();await hydratePhotoImages(document.querySelector('#sheet'))}
async function compare(){const withPhotos=s.checkins.filter(c=>c.photos?.length);if(withPhotos.length<2){toast('Necesitas dos check-ins con fotos');return}const a=withPhotos[0],b=withPhotos.at(-1),ap=await photoGet(a.photos[0]),bp=await photoGet(b.photos[0]);modal(`<h2>Antes ↔ Ahora</h2><div class="compareSlider"><img src="${ap}" class="compareBase"><div class="compareTop" id="compareTop"><img src="${bp}"></div><div class="compareLine" id="compareLine"></div></div><input id="compareRange" class="compareRange" type="range" min="0" max="100" value="50"><div class="compareLabels"><span>ANTES · ${a.date}</span><span>AHORA · ${b.date}</span></div><div class="compareStats"><span>${a.weight||'—'} → ${b.weight||'—'} kg</span><span>${a.waist||'—'} → ${b.waist||'—'} cm cintura</span></div><p class="note">Mueve el deslizador para comparar. Las fotos no se envían a Gemini.</p>`);const r=document.querySelector('#compareRange'),top=document.querySelector('#compareTop'),line=document.querySelector('#compareLine');const move=()=>{top.style.width=r.value+'%';line.style.left=r.value+'%'};r.oninput=move;move()}
async function exportData(){const copy=JSON.parse(JSON.stringify(s));for(const c of copy.checkins||[])for(let i=0;i<(c.photos||[]).length;i++)c.photos[i]=await photoGet(c.photos[i]);for(const d of Object.values(copy.days||{}))for(const m of d.meals||[])if(m.photoRef)m.photoRef=await photoGet(m.photoRef);copy.backupVersion=21;copy.exportedAt=new Date().toISOString();const blob=new Blob([JSON.stringify(copy,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`susu-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Backup completo · incluye fotos')}
function bindSheet(){document.querySelectorAll('[data-food]').forEach(b=>b.onclick=()=>{const f=foods[+b.dataset.food];addMeal({...f,id:id(),at:new Date().toISOString(),source:'quick'})});document.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>action(b.dataset.act))}
