function dayDetail(k){const st=dayStatus(k),d=s.days[k]||{meals:[]};targetDay=k;modal(`<button class="back" data-act="close">‹ Progreso</button><h2>${new Date(k+'T12:00').toLocaleDateString('es',{day:'numeric',month:'long'})}</h2><div class="dayDetail"><div><span>Flexiones</span><b>${st.pushTotal} / ${s.profile.pushGoal} ${st.push?'✓':''}</b></div><div><span>Proteína</span><b>${Math.round(st.p)} / ${s.profile.proteinGoal} g ${st.protein?'✓':''}</b></div><div><span>Calorías</span><b>${Math.round(st.kcal)} kcal</b></div></div><div class="dayEditActions"><button class="secondary" data-act="dailySummary">Resumen del día</button><button class="secondary" data-act="customPush">＋ Flexiones</button><button class="secondary" data-act="food">＋ Comida</button></div>${d.meals?.length?`<div class="meal-list">${d.meals.map(m=>`<div class="meal"><div><b>${esc(m.name)}</b><small>${Math.round(m.kcal)} kcal · ${Math.round(m.p)}g proteína</small></div><button class="del" data-oldmeal="${m.id}" data-oldkey="${k}">×</button></div>`).join('')}</div>`:'<div class="empty">Sin comidas registradas.</div>'}<p class="note">Puedes corregir días anteriores. Los nuevos registros se guardarán en esta fecha.</p>`);document.querySelectorAll('[data-oldmeal]').forEach(b=>b.onclick=()=>{if(!confirm('¿Eliminar esta comida?'))return;const d=day(b.dataset.oldkey),removed=d.meals.find(m=>m.id===b.dataset.oldmeal),prev=[...d.meals];d.meals=d.meals.filter(m=>m.id!==b.dataset.oldmeal);if(!save()){d.meals=prev;return}if(removed?.photoRef)photoDelete(removed.photoRef).catch(()=>{});dayDetail(b.dataset.oldkey)});bindSheet()}
async function lookupBarcode(code){
 code=String(code||'').replace(/\D/g,'');if(code.length<8){toast('Código no válido');return}
 modal(`<h2>Buscando producto…</h2><p class="note">${esc(code)}</p>`);
 try{
  const url=`https://world.openfoodfacts.org/api/v2/product/${encodeURIComponent(code)}.json?fields=code,product_name,product_name_es,brands,nutriments,serving_size`;
  const r=await fetch(url);if(!r.ok)throw Error('HTTP '+r.status);const x=await r.json(),p=x.product,nut=p?.nutriments||{};
  const kcal=n(nut['energy-kcal_100g']),protein=n(nut.proteins_100g),carbs=n(nut.carbohydrates_100g),fat=n(nut.fat_100g);
  if(!p||!kcal){barcodeNotFound(code);return}
  foodAmount({name:p.product_name_es||p.product_name||[p.brands,'Producto'].filter(Boolean).join(' · '),kcal,p:protein,c:carbs,f:fat,unit:'g',barcode:code});
 }catch(e){barcodeNotFound(code)}
}
function barcodeNotFound(code){modal(`<h2>No lo encontré</h2><p class="note">El código ${esc(code)} no está disponible o no tiene nutrición completa. Puedes escanear la etiqueta nutricional y SU SU lo guardará.</p><button class="primary" data-act="labelScan">Escanear etiqueta</button><button class="secondary" data-act="barcode">Probar otro código</button><button class="secondary" data-act="food">Volver</button>`);bindSheet()}
function barcodeModal(){modal(`<h2>Código de barras</h2><p class="note">Haz una foto del código o escríbelo. SU SU consulta Open Food Facts; revisa siempre los valores antes de añadir.</p><p class="note">Datos de productos: Open Food Facts (ODbL).</p><button class="primary" id="takeBarcode">▦ Fotografiar código</button><form id="barcodeForm"><input class="input" name="code" inputmode="numeric" placeholder="EAN / UPC" required><button class="secondary">Buscar código</button></form><button class="secondary" data-act="food">Volver</button>`);document.querySelector('#takeBarcode').onclick=()=>document.querySelector('#barcodeCamera').click();document.querySelector('#barcodeForm').onsubmit=e=>{e.preventDefault();lookupBarcode(new FormData(e.target).get('code'))};bindSheet()}
async function scanBarcodeImage(file){
 try{
  if('BarcodeDetector'in window){const det=new BarcodeDetector({formats:['ean_13','ean_8','upc_a','upc_e']});const bmp=await createImageBitmap(file),codes=await det.detect(bmp);if(codes[0]?.rawValue){lookupBarcode(codes[0].rawValue);return}}
 }catch{}
 const data=await compress(file,1200,.82);analyzeBarcodeWithAI(data);
}
async function analyzeBarcodeWithAI(data){
 if(!s.profile.geminiEndpoint){barcodeModal();return}
 modal(`<h2>Leyendo código…</h2><img class="aiPreview" src="${data}">`);
 try{const r=await fetch(s.profile.geminiEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({image:data,mode:'barcode'})});const x=await r.json();if(!r.ok||!x.barcode)throw Error();lookupBarcode(x.barcode)}catch{barcodeModal();toast('No pude leerlo · escribe el número')}
}
function labelScanStart(){document.querySelector('#labelCamera').click()}
